    (1::int, 999999::int, 0::int, 'SIN PROVEEDOR ASIGNADO'::text, 'SIN PROVEEDOR ASIGNADO'::text, null::text, 'NOASIGNADO'::text, null::text, null::text, null::text, null::text, null::text, 1::int, 'S'::text, false::boolean, 'A'::text, 'SIN PROVEEDOR ASIGNADO'::text, 'SIN PROVEEDOR ASIGNADO'::text, null::int, false::boolean, null::int, null::text, null::timestamp, null::text, null::int, null::int, 'C'::text, null::int, true::boolean, null::text, null::int, false::boolean, null::text),
